#define _XOPEN_SOURCE 600
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <stdio.h>
#include <termios.h>

int main() {
    int master, slave;
    char *name;
    struct winsize ws = {24, 80, 0, 0};

    master = posix_openpt(O_RDWR | O_NOCTTY);
    grantpt(master);
    unlockpt(master);
    name = ptsname(master);
    slave = open(name, O_RDWR);

    ioctl(slave, TIOCSWINSZ, &ws);

    if (fork() == 0) {
        close(master);
        setsid();
        ioctl(slave, TIOCSCTTY, 0);
        setenv("TERM", "xterm-256color", 1);
        execl("./executable", "executable", NULL);
    } else {
        close(slave);
        sleep(2);

        int flags = fcntl(master, F_GETFL, 0);
        fcntl(master, F_SETFL, flags | O_NONBLOCK);

        char buf[4096];
        int n;
        FILE *f = fopen("tui_output_c.txt", "w");
        while ((n = read(master, buf, sizeof(buf))) > 0) {
            fwrite(buf, 1, n, f);
        }
        fclose(f);

        write(master, "q", 1);
        sleep(1);

        kill(0, 9);
    }
    return 0;
}
