{"command":"cat <<'EOF' > capture_pty_spawn.py
import pty
import os
import time

pid, fd = pty.fork()
if pid == 0:
    os.environ['TERM'] = 'xterm-256color'
    os.environ['COLUMNS'] = '80'
    os.environ['LINES'] = '24'
    os.execv('/usr/bin/timeout', ['timeout', '3', './executable', 'dummy_repo'])
else:
    data = b""
    os.set_blocking(fd, False)
    while True:
        try:
            chunk = os.read(fd, 4096)
            if chunk:
                data += chunk
            else:
                break
        except BlockingIOError:
            time.sleep(0.1)
        except OSError as e:
            if e.errno == 5:
                break
            else:
                raise

        # Check if child is dead
        res = os.waitpid(pid, os.WNOHANG)
        if res != (0, 0):
            break

    with open('tui_spawn.bin', 'wb') as f:
        f.write(data)

